#!/bin/bash
# DNS (dnsmasq) helpers — used on Mac 1 (primary) and Mac 3 (backup).

REC="$STATE/records.env"
rec_load() { APP_TARGET="$MAC2_IP"; API_TARGET="$MAC2_IP"; [ -f "$REC" ] && source "$REC"; }
rec_save() { printf 'APP_TARGET=%s\nAPI_TARGET=%s\n' "$APP_TARGET" "$API_TARGET" > "$REC"; }

dns_write_conf() {  # dns_write_conf "primary DNS on Mac 1"
  rec_load
  local who="$1"
  mkdir -p "$PREFIX/var/log"
  cat > "$PREFIX/etc/dnsmasq.conf" <<EOF
# dnsmasq for ${DOMAIN} — ${who} (${MYIP})
# Generated by cn-phase2-kit on $(date '+%Y-%m-%d %H:%M')

# Where to listen: this Mac itself + its LAN address (never only 127.0.0.1)
interface=${IFACE}
listen-address=127.0.0.1,${MYIP}

# Names that are not ours go to public DNS
no-resolv
server=1.1.1.1
server=8.8.8.8
domain-needed
bogus-priv

# Our private zone: answered here only, never sent to the internet
local=/${DOMAIN}/
address=/${APP}/${APP_TARGET}
address=/${API}/${API_TARGET}
# Shows which DNS server answered (handy for the failover demo)
txt-record=dns-server.${DOMAIN},"${who} (${MYIP})"

# Short TTL so caching and cutover are visible (Phase 2, Ext B/E)
local-ttl=${DNS_TTL}

log-queries
log-facility=${PREFIX}/var/log/dnsmasq.log
EOF
  info "Records: ${APP} -> ${APP_TARGET}   ${API} -> ${API_TARGET}   TTL ${DNS_TTL}s"
}

dns_restart() {
  local other
  other="$(sudo lsof -nP -i :53 2>/dev/null | awk 'NR>1 && $1!="dnsmasq"{print $1}' | sort -u | tr '\n' ' ')"
  [ -n "$other" ] && warn "Something else is using port 53: $other — stop it if dnsmasq fails."
  if dnsmasq --test --conf-file="$PREFIX/etc/dnsmasq.conf" 2>&1 | grep -q "syntax check OK"; then ok "Config syntax OK"
  else bad "Config syntax error:"; dnsmasq --test --conf-file="$PREFIX/etc/dnsmasq.conf"; return 1; fi
  sudo touch "$PREFIX/var/log/dnsmasq.log"
  sudo brew services restart dnsmasq >/dev/null 2>&1 || sudo brew services start dnsmasq >/dev/null 2>&1
  sleep 2
  local got; got="$(dig @127.0.0.1 "$APP" +short +time=2 +tries=1 | tail -1)"
  if [ "$got" = "$APP_TARGET" ]; then ok "dnsmasq is answering: ${APP} -> ${got}"
  else bad "dnsmasq did not answer correctly (got '${got:-nothing}', expected $APP_TARGET)"; show "sudo lsof -nP -i :53"; return 1; fi
  got="$(dig @"$MYIP" "$APP" +short +time=2 +tries=1 | tail -1)"
  [ "$got" = "$APP_TARGET" ] && ok "Also answering on the LAN address $MYIP (other Macs can use it)" \
                             || bad "Not answering on $MYIP — check Firewall is off and interface=$IFACE is right"
}

# Which DNS servers this Mac uses. mode: phase1 | phase2
set_resolvers() {
  local mode="$1" svc list
  svc="$(wifi_service)"; [ -z "$svc" ] && svc="Wi-Fi"
  if [ "$mode" = "phase2" ]; then
    case "$THIS_MAC" in
      1) list="127.0.0.1 $MAC3_IP" ;;
      3) list="$MAC1_IP 127.0.0.1" ;;
      *) list="$MAC1_IP $MAC3_IP" ;;
    esac
  else
    [ "$THIS_MAC" = "1" ] && list="127.0.0.1" || list="$MAC1_IP"
  fi
  echo "$mode" > "$STATE/resolver-mode"
  info "Network service: $svc  ->  DNS servers: $list"
  # shellcheck disable=SC2086
  sudo networksetup -setdnsservers "$svc" $list
  flush_dns
  show "scutil --dns | grep 'nameserver\[' | head -4"
}
